using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class DestinationAudit {
 static float[] V(Vector3 p)=>new[]{p.x,p.y,p.z};static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved Edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var g=root.Find("Destination_Colour_Guidance");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));string o=repo+"/Docs/검수/2026-11-08_B5_DestinationColors/";var before=JObject.Parse(File.ReadAllText(o+"before.json"));var current=JArray.Parse(JsonConvert.SerializeObject(root.GetComponentsInChildren<Transform>(true).Select(t=>new{path=P(t),position=V(t.localPosition),rotation=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf}).ToArray()));var changes=before["hierarchy"].Where(j=>!current.Any(k=>JToken.DeepEquals(j,k))).Select(j=>(string)j["path"]).ToArray();var lights=JArray.Parse(JsonConvert.SerializeObject(root.GetComponentsInChildren<Light>(true).Select(l=>new{path=P(l.transform),enabled=l.enabled,active=l.gameObject.activeInHierarchy,position=V(l.transform.position),rotation=V(l.transform.eulerAngles),l.intensity,l.range,l.spotAngle,color=V(new Vector3(l.color.r,l.color.g,l.color.b)),type=l.type.ToString(),shadows=l.shadows.ToString()}).ToArray()));var lightChanges=before["lights"].Where(j=>!lights.Any(k=>JToken.DeepEquals(j,k))).Select(j=>(string)j["path"]).ToArray();
 var meshes=new List<object>();int degenerate=0,down=0,total=0;foreach(var mf in g.GetComponentsInChildren<MeshFilter>()){var m=mf.sharedMesh;var vs=m.vertices;var ts=m.triangles;int bad=0,flipped=0;for(int i=0;i<ts.Length;i+=3){var n=Vector3.Cross(vs[ts[i+1]]-vs[ts[i]],vs[ts[i+2]]-vs[ts[i]]);if(n.sqrMagnitude<1e-14f)bad++;if(n.y<-.000001f)flipped++;}degenerate+=bad;down+=flipped;total+=ts.Length/3;meshes.Add(new{name=mf.name,triangles=ts.Length/3,degenerate=bad,downward=flipped});}
 var renderers=g.GetComponentsInChildren<Renderer>();var scenePaints=renderers.SelectMany(r=>r.sharedMaterials).Distinct().Select(m=>new{m.name,color=ColorUtility.ToHtmlStringRGB(m.GetColor("_BaseColor")),emission=m.IsKeywordEnabled("_EMISSION")}).ToArray();var result=new{scene=s.path,dirty=s.isDirty,meshes,triangles=total,degenerate,downward=down,missingMaterials=renderers.Sum(r=>r.sharedMaterials.Count(m=>!m||!m.shader)),oldMainGuidesActive=root.Find("Facility_Floor_Guidance_R1").GetComponentsInChildren<Renderer>().Count(r=>r.enabled),oldC04GuideActive=root.Find("C02_Security_Art/SC_R1_T05_ToC04").GetComponent<Renderer>().enabled,protectedTransformChanges=changes,lightCount=lights.Count,lightChanges,newColliders=g.GetComponentsInChildren<Collider>().Length,newBehaviours=g.GetComponentsInChildren<MonoBehaviour>().Length,scenePaints};File.WriteAllText(o+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
